import "./trace-viewer-core.js";
import "./producer-experiment-model.js";
const M = globalThis.PRODUCER_EXPERIMENT_MODEL;
const source = await Deno.readTextFile(
  new URL("./producer-experiment-data.js", import.meta.url),
);
const raw = globalThis.TRACE_VIEWER_CORE.parseJsonArtifact(source, {
  assignment: "globalThis.PRODUCER_EXPERIMENT_DATA =",
  generatedComment:
    "// Generated by generate_producer_experiment; do not edit.",
});
function assert(ok, why = "assertion failed") {
  if (!ok) throw new Error(why);
}
function rejects(fn) {
  let caught = false;
  try {
    fn();
  } catch {
    caught = true;
  }
  assert(caught, "corruption accepted");
}
function corrupt(name, edit, bundle = false) {
  Deno.test(name, () => {
    const b = structuredClone(raw);
    edit(bundle ? b : b.runs[0]);
    rejects(() => M.validateData(b));
  });
}
Deno.test("sample accepts raw JSON and the exact inert wrapper", () => {
  const b = M.parseArtifactText(source);
  assert(b.runs[0].summary.records.acked === 48);
  assert(M.parseArtifactText(JSON.stringify(raw.runs[0])).runs.length === 1);
  assert(b.runs[0].numeric.buckets.global.acked instanceof Float64Array);
  rejects(() => M.parseArtifactText(source + "alert(1)"));
  rejects(() =>
    M.parseArtifactText(source.replace("// Generated by", "// Forged by"))
  );
  rejects(() =>
    M.parseArtifactText("globalThis.PRODUCER_EXPERIMENT_DATA = (()=>({}))();")
  );
});
Deno.test("a bounded bundle of sparse topologies may exceed one run's work limit", () => {
  const b = structuredClone(raw);
  const r = b.runs[0];
  const n = r.buckets.count;
  const topic = r.topology.topics[0];
  for (let p = r.topology.partitions.length; p < 1024; p++) {
    r.topology.partitions.push({ topic_id: topic.id_hex, partition: p });
    topic.initial_leaders.push(1);
    r.partitions.acked.push(Array(n).fill(0));
    r.partitions.not_written.push(Array(n).fill(0));
    r.partitions.leader.push(Array(n).fill(1));
  }
  b.seeds = Array.from({ length: 32 }, (_, i) => String(i));
  b.runs = b.seeds.map((seed) => {
    const run = structuredClone(r);
    run.meta.seed = seed;
    return run;
  });
  b.page = { index: 0, count: 1, total_runs: 32 };
  assert(32 * 1024 * n * 3 > 8_000_000);
  const text = JSON.stringify(b);
  assert(new TextEncoder().encode(text).length < 48 * 1024 * 1024);
  const parsed = M.parseArtifactText(text);
  assert(parsed.runs.length === 32);
  assert(parsed.runs[31].topology.partitions[1023].partition === 1023);
});
for (
  const [name, edit] of [
    ["schema", (r) => r.schema = 2],
    [
      "descriptor admission policy",
      (r) => r.config.descriptor_admission_policy = "unbounded",
      (r) => r.config.batch_target_mode = "unbounded",
    ],
    [
      "1025 partition rows",
      (r) => r.topology.partitions = Array(1025).fill(r.topology.partitions[0]),
    ],
    ["partition index 1024", (r) => r.topology.partitions[0].partition = 1024],
    ["unknown run field", (r) => r.extra = true],
    ["category", (r) => r.meta.scenario.category = "random"],
    ["size", (r) => r.meta.size = "tiny"],
    ["unsafe absolute number", (r) => r.meta.origin_ns = 9007199254740992],
    ["noncanonical decimal", (r) => r.meta.seed = "00"],
    ["u64 overflow", (r) => r.meta.seed = "18446744073709551616"],
    ["absolute delta", (r) => r.meta.end_ns = r.meta.origin_ns],
    [
      "broker duplicate",
      (r) => r.topology.brokers[1].id = r.topology.brokers[0].id,
    ],
    ["initial leader", (r) => r.topology.topics[0].initial_leaders[0] = 999],
    [
      "partition duplicate",
      (r) => r.topology.partitions[1] = r.topology.partitions[0],
    ],
    ["broker series", (r) => r.buckets.brokers[0].broker = 999],
    ["series length", (r) => r.buckets.global.acked.pop()],
    ["summary total", (r) => r.summary.records.acked++],
    ["bucket sum", (r) => r.buckets.global.offered_due[0]++],
    ["quantile order", (r) => r.summary.latency_acked.p50 = r.meta.duration],
    ["record order", (r) => r.records.record_id[1] = r.records.record_id[0]],
    ["record due", (r) => r.records.due[0] = r.meta.duration],
    ["record outcome", (r) => r.records.outcome[0] = 4],
    ["reason code", (r) => r.records.reason[0] = 4096],
    ["record column", (r) => r.records.deliver.pop()],
    ["delivery missing", (r) => r.records.deliver[0] = null],
    ["record partition", (r) => r.records.partition[0] = 256],
    ["record broker", (r) => r.records.broker[0] = 999],
    ["negative offset", (r) => r.records.offset[0] = "-1"],
    ["offset overflow", (r) => r.records.offset[0] = "9223372036854775808"],
    ["false completeness", (r) => r.records.complete = false],
    ["complete record quantile", (r) => r.summary.latency_acked.p50--],
    [
      "band order",
      (r) => r.environment.bands[0].end = r.environment.bands[0].start,
    ],
    ["band enum", (r) => r.environment.bands[0].kind = "made-up"],
    ["band realization", (r) => r.environment.bands[0].realized_end = null],
    ["marker order", (r) => r.environment.markers[0].at = r.meta.duration],
    ["marker enum", (r) => r.environment.markers[0].kind = "eval"],
    [
      "credit capacity",
      (r) =>
        r.buckets.global.credits.held_observed_max[0][0] =
          r.buckets.global.credits.capacity[0] + 1,
    ],
    ["outstanding accounting", (r) => r.buckets.global.outstanding[0]++],
    [
      "ECDF rank",
      (r) => r.distributions.latency_ecdf.points.at(-1).cumulative_count--,
    ],
    [
      "ECDF ordering",
      (r) => r.distributions.latency_ecdf.points[0].latency = r.meta.duration,
    ],
    [
      "attempts population",
      (r) => r.distributions.attempts_histogram[0].count++,
    ],
    ["reason population", (r) => r.distributions.outcomes_by_reason[0].count++],
    ["HDR metrics", (r) => r.hdr.metric_names[0] = "Fake"],
    ["HDR scope", (r) => r.hdr.scopes[0].kind = "fake"],
    ["HDR epochs", (r) => r.hdr.intervals.epoch[1] = r.hdr.intervals.epoch[0]],
    ["HDR times", (r) => r.hdr.intervals.taken[0] = r.meta.duration + 1],
    ["HDR duplicate", (r) => r.hdr.series[1] = r.hdr.series[0]],
    ["HDR empty ranges", (r) => {
      const row = r.hdr.series.find((s) => s.count.includes(0));
      row.p50_range[row.count.indexOf(0)] = [0, 0];
    }],
    ["HDR inverted ranges", (r) => {
      const row = r.hdr.series.find((s) => s.count.some((c) => c > 0));
      row.p50_range[row.count.findIndex((c) => c > 0)] = [2, 1];
    }],
    [
      "phase witnesses",
      (r) => r.phase_evidence[0].witnesses.accepted[0] = "01",
    ],
    ["4097 buckets", (r) => r.buckets.count = 4097],
    ["65537 rows", (r) => r.records.count = 65537],
    ["1000001 population", (r) => r.records.population_count = 1000001],
    ["oversized string", (r) => r.meta.scenario.description = "x".repeat(4097)],
  ]
) corrupt(`rejects ${name}`, edit);
corrupt("rejects duplicate bundle run", (b) => b.runs.push(b.runs[0]), true);
corrupt("rejects 33 runs", (b) => b.runs = Array(33).fill(b.runs[0]), true);
corrupt("rejects duplicate bundle seed", (b) => b.seeds.push(b.seeds[0]), true);
corrupt("rejects invalid page", (b) => b.page.index = b.page.count, true);
Deno.test("full width identities and absolute times retain every bit", () => {
  const r = structuredClone(raw.runs[0]);
  r.meta.origin_ns = "18446743000000000000";
  r.meta.end_ns = String(BigInt(r.meta.origin_ns) + BigInt(r.meta.duration));
  r.meta.seed = "18446744073709551615";
  r.records.record_id = r.records.record_id.map((_, i) =>
    String(18446744073709550000n + BigInt(i))
  );
  r.records.offset[0] = "9223372036854775807";
  const v = M.validateData(r).runs[0];
  assert(v.exact.seed === (1n << 64n) - 1n);
  assert(v.exact.recordIds[1] - v.exact.recordIds[0] === 1n);
  assert(v.exact.offsets[0] === (1n << 63n) - 1n);
});
Deno.test("sampled rows never replace population distributions or bucket totals", () => {
  const r = structuredClone(raw.runs[0]);
  for (
    const k of [
      "record_id",
      "due",
      "offer",
      "accept",
      "deliver",
      "outcome",
      "reason",
      "producer_attempts",
      "client_dispatches",
      "partition",
      "broker",
      "offset",
    ]
  ) r.records[k] = r.records[k].filter((_, i) => i % 2 === 0);
  r.records.count /= 2;
  r.records.complete = false;
  const v = M.validateData(r).runs[0],
    slice = M.derive.sampledRecordSlice(v, [0, v.meta.duration]);
  assert(
    slice.indices.length === 24 && slice.populationCount === 48 &&
      !slice.complete,
  );
  assert(
    v.distributions.latency_ecdf.population_count === 48 &&
      v.summary.records.acked === 48,
  );
  const corrupt = structuredClone(r);
  corrupt.records.complete = true;
  rejects(() => M.validateData(corrupt));
});
Deno.test("HDR equivalent ranges may exceed exact maximum", () => {
  const r = structuredClone(raw.runs[0]);
  const row = r.hdr.series.find((s) => s.count.some((c) => c > 0));
  const i = row.count.findIndex((c) => c > 0), max = row.exact_max[i];
  for (const k of ["p50_range", "p90_range", "p99_range", "p999_range"]) {
    row[k][i] = [max, max + 10];
  }
  M.validateData(r);
});
Deno.test("derivation defines inclusive view and bucket resolution with exact marker times", () => {
  const r = M.validateData(raw).runs[0], d = M.derive;
  assert(
    JSON.stringify(d.viewRange(r, [-1, 1e12])) ===
      JSON.stringify([0, r.meta.duration]),
  );
  const slice = d.bucketSlice(r, [50e6, 80e6]);
  assert(slice.start === 50 && slice.end === 81 && slice.resolutionNs === 1e6);
  const rows = d.sampledRecordSlice(r, [50e6, 80e6]);
  assert(rows.indices.length === 16 && rows.counts[0] === 16);
  const steps = d.markersAsSteps(r);
  assert(
    steps.length === r.environment.markers.length &&
      steps[0]._startedAt === BigInt(r.environment.markers[0].at),
  );
  rejects(() => d.viewRange(r, [20, 10]));
});

Deno.test("a paginated bundle may retain seed and variant metadata for other pages", () => {
  const b = structuredClone(raw);
  b.seeds = Array.from({ length: 33 }, (_, i) => String(i));
  b.page = { index: 0, count: 2, total_runs: 33 };
  assert(M.validateData(b).runs.length === 1);
});

Deno.test("experiment overview explains the question and actual run parameters", () => {
  const r = structuredClone(raw.runs[0]);
  r.meta.scenario.id = "baseline.closed-loop-inflight";
  r.meta.size = "full";
  r.meta.workload.active_intervals = [{
    start: 0,
    topic: 0,
    value_bytes: 512,
    key_bytes: 8,
    partitioning: { Keyed: { keys: 64, skew_ppm: 500000 } },
    value_pattern: "Compressible",
    shape: { ClosedLoop: { start_ns: 0, count: 4096, outstanding: 16 } },
  }];
  r.meta.variant.deltas.outstanding = 16;
  r.config.max_in_flight_per_connection = 1;
  const other = structuredClone(r);
  other.meta.variant.deltas.outstanding = 64;
  other.meta.workload.active_intervals[0].shape.ClosedLoop.outstanding = 64;
  other.config.max_in_flight_per_connection = 5;
  const bundle = {
    runs: [r, other],
    page: { index: 0, count: 1, total_runs: 2 },
  };
  const o = M.derive.experimentOverview(r, bundle);
  assert(o.intent.includes("How much work"));
  assert(o.comparison.includes("outstanding record limit: 16 / 64"));
  assert(o.comparison.includes("requests per connection: 1 / 5"));
  assert(
    o.traffic[0].includes("4,096 records") &&
      o.traffic[0].includes("512 bytes per value"),
  );
  assert(o.traffic[0].includes("50% preferred-key branch"));
  assert(
    o.reading.some((s) =>
      s.includes("stop that source offering to healthy partitions")
    ),
  );
  other.meta.workload.active_intervals[0].shape.ClosedLoop.count = 128;
  other.meta.size = "test";
  const changed = M.derive.experimentOverview(other, bundle);
  assert(changed.traffic[0].includes("128 records"));
  assert(changed.settings.includes("5 requests per connection"));
  assert(changed.reading.some((s) => s.includes("smaller Test fixture")));
});

Deno.test("overview distinguishes budgets, offers, setup delay and response-path faults", () => {
  const r = structuredClone(raw.runs[0]);
  r.meta.workload.active_intervals = [
    {
      shape: {
        ClosedLoopUntil: {
          start_ns: 0,
          end_ns: 15e9,
          outstanding: 32,
          max_offers: 900000,
        },
      },
    },
    { shape: { OpenLoop: { start_ns: 1e9, end_ns: 2e9, rate_per_s: 4000 } } },
  ];
  r.environment.bands = [
    {
      broker: 1,
      start: 10e9,
      end: 15e9,
      kind: "service_delay",
      value: {
        api: null,
        phase: "Setup",
        probability_ppm: 1000000,
        effects: { delay_ns: 900e6 },
      },
    },
    {
      broker: 1,
      start: 10e9,
      end: 13e9,
      kind: "link_outage",
      direction: "FromBroker",
      mode: "BlackHole",
    },
  ];
  const o = M.derive.experimentOverview(r, { runs: [r], page: { count: 1 } });
  assert(o.traffic[0].includes("ceiling, not a fixed offered count"));
  assert(o.traffic[1].includes("4,000 records/s from 1 s to 2 s"));
  assert(
    o.faults[0].includes("900 ms") && o.faults[0].includes("connection setup"),
  );
  assert(o.faults[1].includes("return response path holds bytes"));
  assert(
    o.reading.some((s) => s.includes("refused offer is recorded permanently")),
  );
});

Deno.test("overview bounds large load programs and groups matching bursts", () => {
  const r = structuredClone(raw.runs[0]);
  r.meta.workload.active_intervals = Array.from({ length: 1000 }, (_, i) => ({
    start: i * 1e6,
    shape: { ClosedLoop: { start_ns: i * 1e6, count: 50, outstanding: 50 } },
  }));
  const b = { runs: [r], page: { count: 2, total_runs: 33 } };
  let o = M.derive.experimentOverview(r, b);
  assert(
    o.traffic.length === 1 &&
      o.traffic[0].includes("1000 matching finite bursts"),
  );
  assert(o.comparison.includes("33 across 2 pages"));
  r.meta.workload.active_intervals[999].shape.ClosedLoop.count = 100;
  o = M.derive.experimentOverview(r, b);
  assert(
    o.traffic.length === 7 && o.traffic[6].includes("994 further load phases"),
  );
  r.meta.workload.active_intervals = [null];
  assert(
    M.derive.experimentOverview(r, b).traffic[0].includes(
      "not described by this viewer",
    ),
  );
});

Deno.test("Test burst explanations use actual counts instead of the requested variant", () => {
  const r = structuredClone(raw.runs[0]);
  r.meta.variant.deltas.extra = { burst: 800 };
  r.meta.workload.active_intervals = [{
    start: 0,
    shape: { ClosedLoop: { start_ns: 0, count: 128, outstanding: 128 } },
  }];
  const other = structuredClone(r);
  other.meta.variant.deltas.extra.burst = 50;
  other.meta.workload.active_intervals[0].shape.ClosedLoop.count = 50;
  const o = M.derive.experimentOverview(r, {
    runs: [other, r],
    page: { count: 1 },
  });
  assert(o.comparison.includes("records per burst: 50 / 128"));
  assert(o.settings.includes("records per burst: 128"));
  assert(!o.comparison.includes("800") && !o.settings.includes("800"));
});
